3	use std::{fs, path::Path};
4	
5	use oxc_allocator::Allocator;
6	use oxc_formatter::{
7	    FormatOptions, Formatter, SortImportsOptions, SortOrder, default_groups,
8	    default_internal_patterns, get_parse_options,
9	};
10	use oxc_parser::Parser;
11	use oxc_span::SourceType;
12	use pico_args::Arguments;
