14	/// Format a JavaScript or TypeScript file
15	fn main() -> Result<(), String> {
16	    let mut args = Arguments::from_env();
17	    let show_ir = args.contains("--ir");
18	    let name = args.free_from_str().unwrap_or_else(|_| "test.js".to_string());
19	
20	    let partition_by_newline = args.contains("--partition_by_newline");
21	    let partition_by_comment = args.contains("--partition_by_comment");
22	    let sort_side_effects = args.contains("--sort_side_effects");
23	    let order = args.opt_value_from_str("--order").unwrap_or(None).unwrap_or(SortOrder::Asc);
24	    let ignore_case = !args.contains("--no_ignore_case");
25	    let newlines_between = !args.contains("--no_newlines_between");
26	
27	    let sort_imports_options = SortImportsOptions {
28	        order,
29	        partition_by_newline,
30	        partition_by_comment,
31	        sort_side_effects,
32	        ignore_case,
33	        newlines_between,
34	        internal_pattern: default_internal_patterns(),
35	        groups: default_groups(),
